#import "Settings/SGModPage.h"
#import "Privacy.h"
static UIViewController*tipsPage(void){return [[SGModPage alloc]initWithTitle:@"Tips" intro:SGRestartNote sections:@[SGSection(@"Tooltips",@[SGKillRow(@"Hide the smart shuffle helper",@"ios-messaging-reduceinterventions-impl.enable_message_smart_shuffle_helper_tooltip"),SGKillRow(@"Hide the data saver tip",@"ios-feature-nowplayingbar.data_saver_tooltip"),SGKillRow(@"Hide the AI playlist creation tip",@"ios-messaging-reduceinterventions-impl.enable_message_your_library_ai_playlist_creation_tooltip")])] footer:nil];}
UIViewController*SGPrivacySettingsPage(void){return [[SGModPage alloc]initWithTitle:@"Privacy & clutter" intro:SGRestartNote sections:@[SGSection(@"Privacy",@[SGSwitchRow(@"Block telemetry",@"Spotify's own events still go out",SGKeyBlockTelemetry)]),SGSection(@"Clutter",@[SGOptionRow(@"Hide the video carousel in Search",nil,SGKeyHideSearchVideos),SGOptionRow(@"Hide social proof in Search",nil,SGKeyHideSocialProof),SGPageRow(@"Tips",^{return tipsPage();})])] footer:nil];}
